package kr.ac.kdu.focurve;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import org.springframework.stereotype.Component;import org.springframework.context.annotation.Profile;
import java.time.*;import java.util.*;import static kr.ac.kdu.focurve.MemberAuth.*;import static kr.ac.kdu.focurve.MemberIntervals.*;
@Profile("member-runtime | local-integration") @Component
class MemberReadModel {
 final MemberAuth a;final MemberExecution e;MemberReadModel(MemberAuth a,MemberExecution e){this.a=a;this.e=e;}
 record Range(long from,long to){}
 Range range(Map<String,String[]> q){if(!q.containsKey("from_date")&&!q.containsKey("to_date")){LocalDate today=LocalDate.now(ZoneId.of("Asia/Seoul"));return new Range(today.minusDays(6).atStartOfDay(ZoneId.of("Asia/Seoul")).toInstant().toEpochMilli(),today.plusDays(1).atStartOfDay(ZoneId.of("Asia/Seoul")).toInstant().toEpochMilli());}LocalDate[] d=Query.dates(q);ZoneId zone=ZoneId.of("Asia/Seoul");return new Range(d[0].atStartOfDay(zone).toInstant().toEpochMilli(),d[1].plusDays(1).atStartOfDay(zone).toInstant().toEpochMilli());}
 List<ObjectNode> accesses(Identity i){List<ObjectNode> rows=new ArrayList<>();Map<String,Integer> counts=new HashMap<>();for(var row:a.db.queryForList("SELECT r.payload,s.record_status,EXISTS(SELECT 1 FROM execution_reports f WHERE f.session_id=s.id AND f.result IN ('FAILED','UNCONFIRMED')) AS failure_present FROM event_receipts r JOIN access_events x ON x.event_id=r.event_id JOIN focus_sessions s ON s.id=r.resolved_session_id WHERE s.user_id=? AND r.status='ACCEPTED' ORDER BY s.id,x.access_seq",i.user())){JsonNode r=e.parse(row.get("payload"));if(i.executor()!=null&&!text(r,"executor_id").equals(i.executor()))continue;JsonNode p=r.path("payload");String key=text(r,"session_id")+":"+text(p,"target_key");int index=counts.merge(key,1,Integer::sum);rows.add(a.obj("event_id",text(r,"event_id"),"session_id",text(r,"session_id"),"executor_id",text(r,"executor_id"),"occurred_at",text(r,"occurred_at"),"event_type",text(r,"event_type"),"target_kind",text(p,"target_kind"),"target_host",text(p,"target_host"),"feature_code",p.hasNonNull("feature_code")?text(p,"feature_code"):null,"target_key",text(p,"target_key"),"access_seq",p.path("access_seq").asLong(),"target_access_index",index,"is_repeat",index>1,"policy_snapshot_id",text(r,"policy_snapshot_id"),"quality",(text(r,"event_type").equals("BLOCKED_FEATURE_ACCESS")&&(Boolean.TRUE.equals(row.get("failure_present"))||row.get("failure_present") instanceof Number n&&n.intValue()!=0))?"REVIEW_REQUIRED":Objects.equals(row.get("record_status"),"COMPLETE")?"COMPLETE":"PARTIAL"));}return rows;}
 boolean match(ObjectNode row,Map<String,String[]>q,Range r){long t=time(row,"occurred_at");if(t<r.from||t>=r.to)return false;for(String k:List.of("session_id","event_type")){String v=Query.single(q,k,null);if(v!=null&&!text(row,k).equals(v))return false;}String host=Query.single(q,"host",null);return host==null||text(row,"target_host").equals(MemberSites.host(host));}
 static List<ObjectNode> latestFirst(List<ObjectNode> source){var ordered=new ArrayList<ObjectNode>(source);ordered.sort(Comparator.comparing((ObjectNode x)->Instant.parse(text(x,"occurred_at"))).thenComparingLong(x->x.path("access_seq").asLong()).thenComparing(x->text(x,"event_id")).reversed());return ordered;}
 ObjectNode accessList(Identity i,Map<String,String[]> q){Query.allowed(q,"from_date","to_date","session_id","host","event_type","cursor","limit");Range r=range(q);String context="ACCESS:"+i.user()+":"+hash(new TreeMap<>(q).entrySet().stream().filter(x->!Set.of("cursor","limit").contains(x.getKey())).map(x->x.getKey()+Arrays.toString(x.getValue())).reduce("",String::concat));long after=Query.cursor(q,context);int limit=Query.limit(q),index=0;ArrayNode items=a.json.createArrayNode();boolean more=false;for(var row:latestFirst(accesses(i))){if(!match(row,q,r))continue;index++;if(index<=after)continue;if(items.size()==limit){more=true;break;}items.add(row);}return Query.page(a,items,more,more?Query.encode(context,after+items.size()):null);}
 ObjectNode accessDetail(Identity i,String id){uuid(id);for(var row:accesses(i))if(text(row,"event_id").equals(id)){ObjectNode result=row.deepCopy();result.set("snapshot",e.parse(a.one("SELECT payload FROM policy_snapshots WHERE id=? AND user_id=?",text(row,"policy_snapshot_id"),i.user()).get("payload")));return result;}throw new Failure(404,"EVENT_NOT_FOUND");}
 ObjectNode metrics(Identity i,Map<String,String[]>q){return new MemberMetrics(a,e,this).summary(i,q);}
 ObjectNode sessions(Identity i,Map<String,String[]>q){Query.allowed(q,"from_date","to_date","status","cursor","limit");Range r=range(q);long after=q.containsKey("cursor")?Query.cursor(q,"SESSION:"+i.user()):Long.MAX_VALUE;int limit=Query.limit(q);String status=Query.single(q,"status",null);ArrayNode result=a.json.createArrayNode();long last=0;boolean more=false;for(var row:a.db.queryForList("SELECT id,body FROM focus_sessions WHERE user_id=? AND id<? ORDER BY id DESC",i.user(),after)){ObjectNode s=e.parse(row.get("body"));if(i.executor()!=null&&!text(s,"executor_id").equals(i.executor())||status!=null&&!text(s,"execution_status").equals(status))continue;if(q.containsKey("from_date")&&(!s.hasNonNull("started_at")||time(s,"started_at")<r.from||time(s,"started_at")>=r.to))continue;if(result.size()==limit){more=true;break;}result.add(s);last=((Number)row.get("id")).longValue();}return Query.page(a,result,more,more?Query.encode("SESSION:"+i.user(),last):null);}
 ObjectNode dashboard(Identity i){ObjectNode sessions=sessions(i,Map.of("limit",new String[]{"20"}));JsonNode current=null;var currentRow=i.executor()==null?a.one("SELECT body FROM focus_sessions WHERE user_id=? AND execution_status NOT IN ('ENDED','START_FAILED') ORDER BY id DESC LIMIT 1",i.user()):a.one("SELECT body FROM focus_sessions WHERE user_id=? AND executor_id=? AND execution_status NOT IN ('ENDED','START_FAILED') ORDER BY id DESC LIMIT 1",i.user(),i.executor());if(currentRow!=null)current=e.parse(currentRow.get("body"));ArrayNode recent=a.json.createArrayNode();var all=sessions.path("items");for(int n=0;n<all.size()&&recent.size()<5;n++)recent.add(all.get(n));List<ObjectNode> raw=latestFirst(accesses(i));ArrayNode access=a.json.createArrayNode();for(int n=0;n<raw.size()&&access.size()<5;n++)access.add(raw.get(n));return a.obj("current_session",current,"recent_sessions",recent,"recent_access",access,"summary",metrics(i,Map.of()));}
}
